INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q519546', 'Nauruan Civil War', 'The Nauruan Civil War was fought from 1878 to 1888, between forces loyal to incumbent King Aweida of Nauru and those seeking to depose him in favour of a rival claimant. The war was preceded by the introduction of firearms to the island and its inhabitants, Nauruans, as a whole.', 1878, NULL, NULL, 1888, NULL, NULL, 'year', '1878–1888', 52, 'https://en.wikipedia.org/wiki/Nauruan_Civil_War'),
  ('Q124607469', 'Australian occupation of Nauru', 'In September 1914 Australia occupied Nauru, then part of German New Guinea, following the start of World War I. This was part of a larger plan by Japan, the United Kingdom, Australia, and New Zealand to intercept Germany''s East Asia Squadron before they could return to Germany. The island continued to be occupied by Australia until the end of the war.', 1914, 9, 9, 1914, 11, 6, 'day', '9 September 1914 – 6 November 1914', 26, 'https://en.wikipedia.org/wiki/Australian_occupation_of_Nauru'),
